struct nglTexture;

struct FEMenuEntry {
    FEMenuEntry *next;
};

class FEGraphicalMenu {
    char layout[0x150];
public:
    FEMenuEntry *entries;
};

class FEMultiMenu : public FEGraphicalMenu {
    FEMenuEntry *first;
    FEMenuEntry *last;
    FEMenuEntry *secondary_cursor;
public:
    virtual void OnActivate();
    virtual void setHigh(FEMenuEntry *menu, bool anim = true);
};

class PhotoWidget {
    char layout[0x10c];
public:
    void Show(nglTexture *texture, char *score, int photoIdx, float fade);
};

class PhotoChallenge {
public:
    int GetNumTaken() const;
    nglTexture *GetPhotoTexture(const int photoIdx);
};

struct Challenges {
    PhotoChallenge *photo;
};

class beach {
public:
    Challenges *get_challenges();
};

class CompressedPhoto {
public:
    void CopyToTexture(nglTexture *texture) const;
};

class Career {
public:
    bool PhotoExistsForLevel(int level);
    CompressedPhoto *GetPhotoForLevel(int index);
};

class game {
public:
    int get_level_id();
};

class PanelQuad;
class BoxText;

class PhotoSaveMenu : public FEMultiMenu {
    PanelQuad *arrowPQs[2][2];
    PanelQuad *highlightPQs[2];
    PhotoWidget photoWidgets[2];
    BoxText *title;
    int leftArrowIdx;
    int rightArrowIdx;
    float arrowHiTimer;
    int *prevMenuPhotoIdx;
public:
    virtual void OnActivate();
};

extern beach *g_beach_ptr;
extern Career *g_career;
extern game *g_game_ptr;

void PhotoSaveMenu::OnActivate(void)
{
    PhotoChallenge *photoChallenge = g_beach_ptr->get_challenges()->photo;
    float fade;
    int otherIdx = 0;
    bool loaded = false;

    FEMultiMenu::OnActivate();

    if (photoChallenge->GetNumTaken() > *prevMenuPhotoIdx) fade = 0.0f;
    else fade = 1.0f;
    photoWidgets[0].Show(photoChallenge->GetPhotoTexture(*prevMenuPhotoIdx), 0, *prevMenuPhotoIdx, fade);

    while (otherIdx == *prevMenuPhotoIdx) otherIdx++;

    if (g_career->PhotoExistsForLevel(g_game_ptr->get_level_id()))
    {
        CompressedPhoto *photo = g_career->GetPhotoForLevel(g_game_ptr->get_level_id());
        photo->CopyToTexture(photoChallenge->GetPhotoTexture(otherIdx));
        loaded = true;
    }

    if (loaded) fade = 0.0f;
    else fade = 1.0f;
    photoWidgets[1].Show(photoChallenge->GetPhotoTexture(otherIdx), 0, otherIdx, fade);

    setHigh(entries->next);
}
